'use client';

import { useEffect, useMemo, useState } from 'react';
import AppShell from '@/components/Navbar';
import { api } from '@/lib/api';

type StudentType = 'regular' | 'irregular';
type DayShort = 'Mon' | 'Tue' | 'Wed' | 'Thu' | 'Fri' | 'Sat';

interface ApiEnvelope<T> {
  success: boolean;
  message: string;
  data: T;
}

interface DashboardStudent {
  id: number;
  student_id: string | null;
  first_name: string;
  last_name: string;
  full_name: string;
  role: string;
  is_irregular: boolean;
}

interface DashboardResponse {
  student: DashboardStudent;
}

interface ScheduleApiRow {
  schedule_id: number;
  room_number: string | null;
  building: string | null;
  course_code: string | null;
  course_title: string | null;
  section_name: string;
  semester: string;
  year_level: number;
  instructor_full_name: string | null;
  day_of_week: string;
  time_start: string;
  time_end: string;
}

interface ScheduleClass {
  id: string;
  subject: string;
  code: string;
  instructor: string;
  room: string;
  building: string;
  day: DayShort;
  time: string;
  type: 'Lecture' | 'Lab';
  isToday: boolean;
}

const DAY_MAP: Record<string, DayShort> = {
  monday: 'Mon',
  tuesday: 'Tue',
  wednesday: 'Wed',
  thursday: 'Thu',
  friday: 'Fri',
  saturday: 'Sat',
};

function to12Hour(time: string) {
  const [h, m] = time.split(':').map(Number);
  const suffix = h >= 12 ? 'PM' : 'AM';
  const hour = h % 12 || 12;
  return `${hour}:${String(m).padStart(2, '0')} ${suffix}`;
}

function mapScheduleRow(row: ScheduleApiRow): ScheduleClass | null {
  const day = DAY_MAP[row.day_of_week.trim().toLowerCase()];
  if (!day) return null;

  const code = row.course_code ?? 'TBA';
  const subject = row.course_title ?? 'Untitled Subject';
  const type: 'Lecture' | 'Lab' = code.toLowerCase().includes('lab') ? 'Lab' : 'Lecture';

  return {
    id: `S${row.schedule_id}`,
    subject,
    code,
    instructor: row.instructor_full_name ?? 'TBA',
    room: row.room_number ?? 'TBA',
    building: row.building ?? 'TBA',
    day,
    time: `${to12Hour(row.time_start)} - ${to12Hour(row.time_end)}`,
    type,
    isToday: false,
  };
}

export default function StudentDashboard() {
  const [scheduleTab, setScheduleTab] = useState<'today' | 'week'>('today');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [student, setStudent] = useState<DashboardStudent | null>(null);
  const [schedule, setSchedule] = useState<ScheduleClass[]>([]);

  useEffect(() => {
    let active = true;
    async function load() {
      setLoading(true);
      setError('');
      try {
        const [studentRes, scheduleRes] = await Promise.all([
          api.get<ApiEnvelope<DashboardResponse>>('/student/dashboard'),
          api.get<ApiEnvelope<ScheduleApiRow[]>>('/student/schedule'),
        ]);

        const today = new Date().toLocaleDateString('en-US', { weekday: 'short' }).slice(0, 3) as DayShort;
        const mapped = (scheduleRes.data ?? [])
          .map(mapScheduleRow)
          .filter((row): row is ScheduleClass => row !== null)
          .map((row) => ({ ...row, isToday: row.day === today }));

        if (!active) return;
        setStudent(studentRes.data.student);
        setSchedule(mapped);
      } catch (e: unknown) {
        if (active) setError(e instanceof Error ? e.message : 'Failed to load dashboard.');
      } finally {
        if (active) setLoading(false);
      }
    }
    load();
    return () => {
      active = false;
    };
  }, []);

  const todayClasses = useMemo(() => schedule.filter((c) => c.isToday), [schedule]);
  const uniqueSubjects = useMemo(() => new Set(schedule.map((c) => c.code)).size, [schedule]);
  const studentName = student?.full_name ?? 'Student';
  const studentId = student?.student_id ?? 'N/A';
  const studentType: StudentType = student?.is_irregular ? 'irregular' : 'regular';
  const initials = studentName.split(' ').map((n) => n[0]).join('').slice(0, 2).toUpperCase();

  return (
    <AppShell role="student" userName={studentName} pageTitle="Dashboard">
      <div className="flex items-start justify-between mb-5 gap-4 flex-wrap">
        <div>
          <h1 className="text-[20px] font-bold" style={{ color: 'var(--color-text)' }}>
            Student Dashboard
          </h1>
          <p className="text-[13px] mt-0.5" style={{ color: 'var(--color-text-muted)' }}>
            {loading ? 'Loading profile...' : `${todayClasses.length} ${todayClasses.length === 1 ? 'class' : 'classes'} today.`}
          </p>
        </div>
      </div>

      {error && (
        <div className="card p-4 mb-5 text-[13px]" style={{ color: 'var(--color-error)' }}>
          {error}
        </div>
      )}

      <div className="mb-5">
        <div className="card flex items-center gap-4" style={{ padding: '14px 20px', boxShadow: 'var(--shadow-sm)' }}>
          <div className="w-11 h-11 rounded-full flex items-center justify-center text-[15px] font-bold" style={{ background: 'var(--color-primary-muted)', color: 'var(--color-primary)' }}>
            {initials}
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-[15px] font-bold" style={{ color: 'var(--color-text)' }}>{studentName}</p>
            <p className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>{studentId}</p>
          </div>
          <span className="text-[11px] font-semibold px-3 py-1 rounded-full" style={studentType === 'irregular' ? { background: '#fff8e6', color: '#92620a' } : { background: 'var(--color-primary-muted)', color: 'var(--color-primary)' }}>
            {studentType === 'irregular' ? 'Irregular' : 'Regular'}
          </span>
        </div>
      </div>

      <div className="grid gap-4 mb-6 grid-cols-2 lg:grid-cols-3">
        <div className="card p-4">
          <p className="text-[26px] font-bold" style={{ color: 'var(--color-primary)' }}>{todayClasses.length}</p>
          <p className="text-[12px]">Classes Today</p>
        </div>
        <div className="card p-4">
          <p className="text-[26px] font-bold" style={{ color: '#3730a3' }}>{uniqueSubjects}</p>
          <p className="text-[12px]">Total Subjects</p>
        </div>
        <div className="card p-4">
          <p className="text-[12px] font-medium">Student ID</p>
          <p className="text-[16px] font-bold">{studentId}</p>
        </div>
      </div>

      <div className="card mb-5">
        <div className="card-body pb-0 flex items-center justify-between">
          <div>
            <h2 className="text-[14px] font-semibold">My Schedule</h2>
            <p className="text-[11.5px] text-[var(--color-text-muted)]">{scheduleTab === 'today' ? 'Today' : 'This Week'}</p>
          </div>
          <div className="flex rounded-lg p-0.5" style={{ background: 'var(--color-surface-2)' }}>
            {(['today', 'week'] as const).map((t) => (
              <button key={t} onClick={() => setScheduleTab(t)} className="px-4 py-1.5 text-[12px] font-semibold rounded-md" style={scheduleTab === t ? { background: 'var(--color-surface)', color: 'var(--color-primary)' } : { color: 'var(--color-text-muted)' }}>
                {t === 'today' ? 'Today' : 'Week'}
              </button>
            ))}
          </div>
        </div>

        <div className="px-6 pb-6">
          {loading ? (
            <div className="py-10 text-center text-[12px] text-[var(--color-text-muted)]">Loading schedule...</div>
          ) : scheduleTab === 'today' ? (
            todayClasses.length ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                {todayClasses.map((cls) => (
                  <div key={cls.id} className="card p-4 flex flex-col gap-2.5" style={{ borderLeft: `3px solid ${cls.type === 'Lab' ? '#6366f1' : 'var(--color-primary-light)'}` }}>
                    <div className="flex items-start justify-between gap-2">
                      <div>
                        <p className="text-[13px] font-semibold" style={{ color: 'var(--color-text)' }}>{cls.subject}</p>
                        <p className="text-[11.5px]" style={{ color: 'var(--color-text-muted)' }}>{cls.code}</p>
                      </div>
                      <span className="text-[10.5px] font-semibold px-2 py-0.5 rounded-full" style={cls.type === 'Lab' ? { background: '#eef2ff', color: '#3730a3' } : { background: 'var(--color-primary-muted)', color: 'var(--color-primary)' }}>
                        {cls.type}
                      </span>
                    </div>
                    <p className="text-[12px]" style={{ color: 'var(--color-text-secondary)' }}>{cls.time}</p>
                    <p className="text-[12px]" style={{ color: 'var(--color-text-secondary)' }}>{cls.room} · {cls.building}</p>
                    <p className="text-[12px]" style={{ color: 'var(--color-text-secondary)' }}>{cls.instructor}</p>
                  </div>
                ))}
              </div>
            ) : (
              <div className="py-10 text-center text-[12px] text-[var(--color-text-muted)]">No classes today</div>
            )
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-2">
              {(['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] as DayShort[]).map((day) => {
                const dayClasses = schedule.filter((c) => c.day === day);
                return (
                  <div key={day} className="rounded-lg border p-2" style={{ borderColor: 'var(--color-border)' }}>
                    <p className="text-[11px] font-semibold mb-2" style={{ color: 'var(--color-text-secondary)' }}>{day}</p>
                    {dayClasses.length ? dayClasses.map((c) => (
                      <div key={`${c.id}-${day}`} className="mb-1 last:mb-0 rounded-md px-2 py-1 text-[10.5px]" style={{ background: 'var(--color-surface-2)' }}>
                        <p className="font-semibold">{c.code}</p>
                        <p style={{ color: 'var(--color-text-muted)' }}>{c.time.split(' - ')[0]}</p>
                      </div>
                    )) : <p className="text-[10px]" style={{ color: 'var(--color-text-muted)' }}>Free</p>}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </AppShell>
  );
}
